// Ins stages a new row, with a setter for every insertable column. A column
// left unset is absent from the statement, so the database default applies;
// a zero value that was set is written.
type Ins struct {
	row Row
	set uint64

	// conflict is the upsert target, as a bit per unique-constraint
	// column set. Zero means a plain insert, and a duplicate is an error
	// — which is the right default: silently updating a row you meant to
	// create is a data-loss bug that looks like success.
	conflict uint8

	// add marks the assigned columns an upsert ACCUMULATES into rather
	// than overwrites. Part of the statement key, beside the mask.
	add uint64
}

// Create stages a new row.
func Create() Ins { return Ins{} }

// Assigned reports the mask, which is also the statement key.
func (n Ins) Assigned() uint64 { return n.set }

// insertArgs appends the values n assigns, in column order.
func (n *Ins) insertArgs(args []any) []any {
	for i := 0; i < nInsertable; i++ {
		if n.set&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, n.row.ID)
		case 1:
			args = append(args, n.row.CreatedAt)
		case 2:
			args = append(args, n.row.UpdatedAt)
		case 3:
			args = append(args, n.row.Name)
		case 4:
			args = append(args, n.row.URL)
		case 5:
			args = append(args, n.row.ExpectStatus)
		case 6:
			args = append(args, n.row.Keyword)
		case 7:
			args = append(args, n.row.EverySeconds)
		case 8:
			args = append(args, n.row.TimeoutSeconds)
		case 9:
			args = append(args, n.row.ConfirmFrom)
		case 10:
			args = append(args, n.row.Paused)
		case 11:
			args = append(args, n.row.Telegram)
		case 12:
			args = append(args, n.row.TelegramBot)
		case 13:
			args = append(args, n.row.TelegramChats)
		case 14:
			args = append(args, n.row.CreatedBy)
		case 15:
			args = append(args, n.row.State)
		case 16:
			args = append(args, n.row.StateSince.Arg())
		case 17:
			args = append(args, n.row.FailingRounds)
		case 18:
			args = append(args, n.row.LastAt.Arg())
		case 19:
			args = append(args, n.row.LastMs.Arg())
		case 20:
			args = append(args, n.row.LastStatus.Arg())
		case 21:
			args = append(args, n.row.LastDetail)
		case 22:
			args = append(args, n.row.LastOutcome)
		case 23:
			args = append(args, n.row.CertNotAfter.Arg())
		case 24:
			args = append(args, n.row.NextAt)
		case 25:
			args = append(args, n.row.LeaseUntil.Arg())
		case 26:
			args = append(args, n.row.Method)
		case 27:
			args = append(args, n.row.RequestBody)
		case 28:
			args = append(args, n.row.HeaderNames)
		case 29:
			args = append(args, n.row.HeadersSealed)
		}
	}
	return args
}

